package com.rebalance.service.image;

import java.io.IOException;

/**
 * Where receipt image bytes live. Keys are generated by the application (letters, digits, '-', '_', '.').
 */
public interface ImageStorage {
    void write(String key, byte[] data) throws IOException;

    /**
     * @return the bytes, or null if nothing is stored under the key
     */
    byte[] read(String key) throws IOException;

    void delete(String key) throws IOException;
}
